<?php
require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/functions.php';require_once dirname(__DIR__).'/includes/csrf.php';$u=require_login();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='GET'){$id=(int)($_GET['conversation_id']??0);$c=$pdo->prepare('SELECT id FROM conversations WHERE id=? AND (buyer_id=? OR seller_id=?)');$c->execute([$id,$u['id'],$u['id']]);if(!$c->fetch()){http_response_code(403);exit;} $s=$pdo->prepare('SELECT m.*,u.name sender_name FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.conversation_id=? ORDER BY m.id');$s->execute([$id]);$items=$s->fetchAll();foreach($items as &$m)$m['mine']=(int)$m['sender_id']===(int)$u['id'];header('Content-Type: application/json');echo json_encode(['items'=>$items]);exit;}
verify_csrf();$action=$_POST['action']??'';if($action==='start'){$listing=(int)($_POST['listing_id']??0);$s=$pdo->prepare("SELECT id,user_id FROM listings WHERE id=? AND status='approved'");$s->execute([$listing]);$l=$s->fetch();if(!$l||(int)$l['user_id']===(int)$u['id']){flash('error','Chat is unavailable for this listing.');redirect('/listing.php?id='.$listing);} $pdo->prepare('INSERT IGNORE INTO conversations(listing_id,buyer_id,seller_id) VALUES(?,?,?)')->execute([$listing,$u['id'],$l['user_id']]);$q=$pdo->prepare('SELECT id FROM conversations WHERE listing_id=? AND buyer_id=? AND seller_id=?');$q->execute([$listing,$u['id'],$l['user_id']]);redirect('/chat.php?conversation_id='.(int)$q->fetchColumn());}
if($action==='send'){$id=(int)($_POST['conversation_id']??0);$msg=trim($_POST['message']??'');$c=$pdo->prepare('SELECT id FROM conversations WHERE id=? AND (buyer_id=? OR seller_id=?)');$c->execute([$id,$u['id'],$u['id']]);if(!$c->fetch()||$msg===''){flash('error','Message could not be sent.');redirect('/messages.php');}$pdo->prepare('INSERT INTO messages(conversation_id,sender_id,message) VALUES(?,?,?)')->execute([$id,$u['id'],$msg]);redirect('/chat.php?conversation_id='.$id);}http_response_code(400);